```javascript
function countSmallerElements(arr) {
  // Сжатый массив уникальных значений
  const sortedUnique = [...new Set(arr)].sort((a, b) => a - b);
  const map = new Map();

  // Сопоставляем уникальные значения с их индексами в отсортированном массиве
  for (let i = 0; i < sortedUnique.length; i++) {
    map.set(sortedUnique[i], i);
  }

  // Массив для хранения количества элементов меньше текущего
  const result = new Array(arr.length).fill(0);

  // Используем структуру данных для подсчёта количества элементов
  const BIT = new BinaryIndexedTree(sortedUnique.length);

  // Обходим массив с конца
  for (let i = arr.length - 1; i >= 0; i--) {
    const val = arr[i];
    const index = map.get(val);
    result[i] = BIT.query(index - 1); // Количество элементов меньше текущего
    BIT.update(index, 1); // Добавляем текущий элемент в структуру
  }

  return result;
}

